"""The kitty itself: members, expenses, payments, and the arithmetic behind them.

All money is handled internally as whole cents (ints) in the base currency, so
totals never drift from rounding. Each expense's split is fixed when it is
added, so changing an exchange rate later does not rewrite past expenses.
"""

import csv
import datetime
import json
import math
import os
import re
import tempfile
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation
from fractions import Fraction

DATA_FILE = "kitty.json"
DEFAULT_CATEGORY = "other"
FORMAT_VERSION = 1
EXPORT_COLUMNS = ["id", "date", "payer", "description", "amount", "currency", "category", "base_amount"]


class KittyError(Exception):
    """A problem with what was typed or with the kitty file, shown to the user as-is."""


# --- Parsing and formatting -------------------------------------------------

def parse_number(text, what):
    try:
        value = Decimal(text.strip())
    except InvalidOperation:
        hint = " (use a dot for decimals, like 12.50)" if "," in text else ""
        raise KittyError(f"{what} '{text}' is not a number{hint}") from None
    if not value.is_finite():
        raise KittyError(f"{what} '{text}' is not a number")
    return value


def parse_positive(text, what):
    value = parse_number(text, what)
    if value <= 0:
        raise KittyError(f"{what} must be more than zero, got '{text}'")
    return value


def parse_cents(text, what):
    value = parse_positive(text, what)
    cents = value * 100
    if cents != cents.to_integral_value():
        raise KittyError(f"{what} '{text}' has more than two decimal places")
    return int(cents)


def format_cents(cents):
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def stored_cents(text):
    return int(Decimal(text) * 100)


def parse_currency(text):
    code = text.strip().upper()
    if not re.fullmatch(r"[A-Z]{3}", code):
        raise KittyError(f"Currency '{text}' should be a three-letter code like EUR or USD")
    return code


def parse_date(text):
    if text is None:
        return datetime.date.today().isoformat()
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", text.strip()):
        raise KittyError(f"Date '{text}' should look like 2026-07-14 (year-month-day)")
    try:
        return datetime.date.fromisoformat(text.strip()).isoformat()
    except ValueError:
        raise KittyError(f"Date '{text}' is not a real date") from None


def parse_id(text, kind="Expense"):
    try:
        return int(text)
    except ValueError:
        raise KittyError(f"{kind} ID '{text}' should be a whole number") from None


def convert(cents, rate):
    return int((Decimal(cents) * rate).quantize(Decimal(1), rounding=ROUND_HALF_UP))


def allocate(total, weights):
    """Split `total` cents in proportion to `weights` ({name: Decimal}).

    Everyone's part is rounded down to the cent, then the leftover cents go one
    each in the order of `weights`, so the parts add up to exactly `total`.
    """
    weight_sum = sum(Fraction(w) for w in weights.values())
    parts = {name: math.floor(total * Fraction(w) / weight_sum) for name, w in weights.items()}
    leftover = total - sum(parts.values())
    for name in list(parts)[:leftover]:
        parts[name] += 1
    return parts


# --- The kitty --------------------------------------------------------------

class Kitty:
    def __init__(self, data, path):
        self.data = data
        self.path = path

    @classmethod
    def create(cls, path, currency):
        if os.path.exists(path):
            raise KittyError(f"There's already a kitty here ({path}). Delete or move it to start a new one.")
        data = {
            "version": FORMAT_VERSION,
            "base_currency": parse_currency(currency),
            "members": [],
            "rates": {},
            "expenses": [],
            "payments": [],
            "next_expense_id": 1,
            "next_payment_id": 1,
            "next_seq": 1,
        }
        kitty = cls(data, path)
        kitty.save()
        return kitty

    @classmethod
    def load(cls, path):
        if not os.path.exists(path):
            raise KittyError("There's no kitty in this folder yet. Start one with: python3 -m kitty init EUR")
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
        except (OSError, ValueError) as e:
            raise KittyError(f"Couldn't read {path}: {e}") from None
        expected = {"base_currency": str, "members": list, "rates": dict, "expenses": list,
                    "payments": list, "next_expense_id": int, "next_payment_id": int, "next_seq": int}
        if not isinstance(data, dict) or any(not isinstance(data.get(k), t) for k, t in expected.items()):
            raise KittyError(f"{path} doesn't look like a kitty file (it may have been damaged)")
        return cls(data, path)

    def save(self):
        # Write to a temporary file and swap it in, so a crash can't leave a half-written kitty.
        directory = os.path.dirname(os.path.abspath(self.path))
        mode = os.stat(self.path).st_mode & 0o777 if os.path.exists(self.path) else 0o644
        fd, tmp = tempfile.mkstemp(dir=directory, prefix=".kitty-", suffix=".tmp")
        try:
            os.chmod(tmp, mode)
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(self.data, f, indent=2, ensure_ascii=False)
                f.write("\n")
            os.replace(tmp, self.path)
        except BaseException:
            try:
                os.remove(tmp)
            except OSError:
                pass
            raise

    @property
    def base(self):
        return self.data["base_currency"]

    @property
    def members(self):
        return self.data["members"]

    def _next(self, counter):
        value = self.data[counter]
        self.data[counter] = value + 1
        return value

    # Members

    def require_member(self, name):
        if name not in self.members:
            listing = ", ".join(self.members) if self.members else "nobody yet"
            raise KittyError(f"'{name}' isn't in the group (members: {listing})")

    def add_member(self, name):
        name = name.strip()
        if not name:
            raise KittyError("A member's name can't be empty")
        if "," in name or "=" in name:
            raise KittyError(f"Name '{name}' can't contain ',' or '=' (they're used in --among, --exact, etc.)")
        for existing in self.members:
            if existing.lower() == name.lower():
                raise KittyError(f"'{existing}' is already in the group")
        self.members.append(name)
        return name

    def remove_member(self, name):
        self.require_member(name)
        involved = any(e["payer"] == name or name in e["shares"] for e in self.data["expenses"])
        involved = involved or any(name in (p["from"], p["to"]) for p in self.data["payments"])
        if involved:
            raise KittyError(f"{name} is part of existing expenses or payments, so removing them would "
                             f"break the balances. Remove those expenses and payments first.")
        self.members.remove(name)

    # Rates

    def set_rate(self, currency, rate_text):
        currency = parse_currency(currency)
        if currency == self.base:
            raise KittyError(f"{currency} is the main currency; its rate is always 1")
        rate = parse_positive(rate_text, "Rate")
        self.data["rates"][currency] = str(rate)
        return currency, rate

    def _resolve_currency(self, currency):
        currency = parse_currency(currency) if currency is not None else self.base
        if currency == self.base:
            return currency, Decimal(1)
        if currency not in self.data["rates"]:
            raise KittyError(f"There's no exchange rate for {currency} yet. "
                             f"Set one first with: python3 -m kitty rate set {currency} RATE")
        return currency, Decimal(self.data["rates"][currency])

    # Expenses

    def _parse_names(self, text):
        names = [n.strip() for n in text.split(",") if n.strip()]
        if not names:
            raise KittyError("--among needs at least one name, like --among Alice,Bob")
        for name in names:
            self.require_member(name)
        if len(set(names)) != len(names):
            raise KittyError("--among lists someone more than once")
        return names

    def _parse_pairs(self, text, option, parse_value):
        result = {}
        for item in text.split(","):
            item = item.strip()
            if not item:
                continue
            name, sep, value = item.partition("=")
            if not sep:
                raise KittyError(f"{option} expects NAME=VALUE pairs separated by commas, "
                                 f"like A=30,B=20 (got '{item}')")
            name = name.strip()
            self.require_member(name)
            if name in result:
                raise KittyError(f"{option} lists {name} more than once")
            result[name] = parse_value(value.strip(), name)
        if not result:
            raise KittyError(f"{option} needs at least one NAME=VALUE pair")
        return result

    def _weights(self, amount, among, exact, shares, percent):
        """Who pays what proportion, in the order that gets leftover cents first:
        the order names were typed, or join order when it's split between everyone."""
        if exact is not None:
            parts = self._parse_pairs(exact, "--exact", lambda v, n: parse_cents(v, f"Amount for {n}"))
            total = sum(parts.values())
            if total != amount:
                raise KittyError(f"The --exact amounts add up to {format_cents(total)}, "
                                 f"but the expense is {format_cents(amount)}")
            weights = {n: Decimal(c) for n, c in parts.items()}
        elif shares is not None:
            weights = self._parse_pairs(shares, "--shares", lambda v, n: parse_positive(v, f"Shares for {n}"))
        elif percent is not None:
            weights = self._parse_pairs(percent, "--percent", lambda v, n: parse_positive(v, f"Percent for {n}"))
            total = sum(weights.values())
            if total != 100:
                raise KittyError(f"The --percent values add up to {total}, not 100")
        else:
            names = self._parse_names(among) if among is not None else list(self.members)
            if not names:
                raise KittyError("There's nobody in the group to split this between. "
                                 "Add people first with: python3 -m kitty member add NAME")
            weights = {n: Decimal(1) for n in names}
        return weights

    def add_expense(self, payer, amount_text, description, currency=None, date=None,
                    category=None, among=None, exact=None, shares=None, percent=None):
        self.require_member(payer)
        amount = parse_cents(amount_text, "Amount")
        description = description.strip()
        if not description:
            raise KittyError("The description can't be empty")
        category = (category if category is not None else DEFAULT_CATEGORY).strip().lower()
        if not category:
            raise KittyError("The category can't be empty")
        currency, rate = self._resolve_currency(currency)
        date = parse_date(date)
        weights = self._weights(amount, among, exact, shares, percent)
        base_amount = convert(amount, rate)
        split = allocate(base_amount, weights)
        # Shares are shown in join order, whatever order decided the leftover cents.
        expense = {
            "id": self._next("next_expense_id"),
            "date": date,
            "payer": payer,
            "description": description,
            "amount": format_cents(amount),
            "currency": currency,
            "base_amount": format_cents(base_amount),
            "category": category,
            "shares": {n: format_cents(split[n]) for n in self.members if n in split},
            "seq": self._next("next_seq"),
        }
        self.data["expenses"].append(expense)
        return expense

    def remove_expense(self, id_text):
        expense_id = parse_id(id_text)
        for expense in self.data["expenses"]:
            if expense["id"] == expense_id:
                self.data["expenses"].remove(expense)
                return expense
        raise KittyError(f"There's no expense with ID {expense_id}")

    def list_expenses(self):
        return [{k: v for k, v in e.items() if k != "seq"} for e in self.data["expenses"]]

    # Payments

    def add_payment(self, sender, receiver, amount_text, currency=None, date=None):
        self.require_member(sender)
        self.require_member(receiver)
        if sender == receiver:
            raise KittyError("Someone can't pay themselves back")
        amount = parse_cents(amount_text, "Amount")
        currency, rate = self._resolve_currency(currency)
        payment = {
            "id": self._next("next_payment_id"),
            "date": parse_date(date),
            "from": sender,
            "to": receiver,
            "amount": format_cents(amount),
            "currency": currency,
            "base_amount": format_cents(convert(amount, rate)),
            "seq": self._next("next_seq"),
        }
        self.data["payments"].append(payment)
        return payment

    def remove_payment(self, id_text):
        payment_id = parse_id(id_text, "Payment")
        for payment in self.data["payments"]:
            if payment["id"] == payment_id:
                self.data["payments"].remove(payment)
                return payment
        raise KittyError(f"There's no payment with ID {payment_id}")

    def list_payments(self):
        return [{k: v for k, v in p.items() if k != "seq"} for p in self.data["payments"]]

    # Reports (all amounts in cents; the CLI formats them)

    def _events(self):
        """Every expense and payment as (date, seq, description, {name: change in cents})."""
        events = []
        for e in self.data["expenses"]:
            changes = {n: -stored_cents(c) for n, c in e["shares"].items()}
            changes[e["payer"]] = changes.get(e["payer"], 0) + stored_cents(e["base_amount"])
            events.append((e["date"], e["seq"], e["description"], changes))
        for p in self.data["payments"]:
            amount = stored_cents(p["base_amount"])
            changes = {p["from"]: amount, p["to"]: -amount}
            events.append((p["date"], p["seq"], f"Payment from {p['from']} to {p['to']}", changes))
        events.sort(key=lambda event: (event[0], event[1]))
        return events

    def balances(self):
        totals = {n: 0 for n in self.members}
        for _, _, _, changes in self._events():
            for name, change in changes.items():
                totals[name] = totals.get(name, 0) + change
        return totals

    def settle(self):
        order = {n: i for i, n in enumerate(self.members)}
        debtors = [[-c, n] for n, c in self.balances().items() if c < 0]
        creditors = [[c, n] for n, c in self.balances().items() if c > 0]
        transfers = []
        while debtors and creditors:
            debtors.sort(key=lambda x: (-x[0], order.get(x[1], 0)))
            creditors.sort(key=lambda x: (-x[0], order.get(x[1], 0)))
            debtor, creditor = debtors[0], creditors[0]
            amount = min(debtor[0], creditor[0])
            transfers.append((debtor[1], creditor[1], amount))
            debtor[0] -= amount
            creditor[0] -= amount
            debtors = [d for d in debtors if d[0]]
            creditors = [c for c in creditors if c[0]]
        return transfers

    def history(self, name):
        self.require_member(name)
        running = 0
        rows = []
        for date, _, description, changes in self._events():
            if name in changes:
                running += changes[name]
                rows.append((date, description, changes[name], running))
        return rows

    def report(self):
        by_category = {}
        for e in self.data["expenses"]:
            totals = by_category.setdefault(e["category"], {})
            for name, share in e["shares"].items():
                totals[name] = totals.get(name, 0) + stored_cents(share)
        order = {n: i for i, n in enumerate(self.members)}
        return {cat: dict(sorted(totals.items(), key=lambda item: order.get(item[0], len(order))))
                for cat, totals in sorted(by_category.items())}

    def export(self, path):
        if os.path.exists(path) and os.path.samefile(path, self.path):
            raise KittyError(f"Exporting to {path} would overwrite the kitty itself; pick another file name")
        try:
            with open(path, "w", newline="", encoding="utf-8") as f:
                writer = csv.writer(f)
                writer.writerow(EXPORT_COLUMNS)
                for e in self.data["expenses"]:
                    writer.writerow([e[column] for column in EXPORT_COLUMNS])
        except OSError as e:
            raise KittyError(f"Couldn't write {path}: {e.strerror}") from None
        return len(self.data["expenses"])
"""Command-line interface: `python3 -m kitty COMMAND ...`.

Reports are printed as JSON; money is a string with two decimals.
Mistakes are reported on stderr with exit status 1.
"""

import argparse
import json
import sys

from . import core


class Parser(argparse.ArgumentParser):
    def error(self, message):
        self.print_usage(sys.stderr)
        self.exit(1, f"{self.prog}: error: {message}\n")


def as_json(value):
    return json.dumps(value, ensure_ascii=False)


def money(cents_by_name):
    return {name: core.format_cents(cents) for name, cents in cents_by_name.items()}


# --- Commands ---------------------------------------------------------------

def cmd_init(args):
    kitty = core.Kitty.create(core.DATA_FILE, args.currency)
    return f"Started a new kitty in {kitty.base}."


def cmd_member_add(kitty, args):
    name = kitty.add_member(args.name)
    kitty.save()
    return f"Added {name}."


def cmd_member_remove(kitty, args):
    kitty.remove_member(args.name)
    kitty.save()
    return f"Removed {args.name}."


def cmd_member_list(kitty, args):
    return as_json(kitty.members)


def cmd_expense_add(kitty, args):
    expense = kitty.add_expense(
        args.payer, args.amount, " ".join(args.description), currency=args.currency, date=args.date,
        category=args.category, among=args.among, exact=args.exact, shares=args.shares, percent=args.percent)
    kitty.save()
    return str(expense["id"])


def cmd_expense_list(kitty, args):
    return as_json(kitty.list_expenses())


def cmd_expense_remove(kitty, args):
    expense = kitty.remove_expense(args.id)
    kitty.save()
    return f"Removed expense {expense['id']} ({expense['description']})."


def cmd_payment_add(kitty, args):
    payment = kitty.add_payment(args.sender, args.receiver, args.amount, currency=args.currency, date=args.date)
    kitty.save()
    return str(payment["id"])


def cmd_payment_list(kitty, args):
    return as_json(kitty.list_payments())


def cmd_payment_remove(kitty, args):
    payment = kitty.remove_payment(args.id)
    kitty.save()
    return f"Removed payment {payment['id']} ({payment['from']} to {payment['to']}, {payment['amount']} {payment['currency']})."


def cmd_rate_set(kitty, args):
    currency, rate = kitty.set_rate(args.currency, args.rate)
    kitty.save()
    return f"1 {currency} = {rate} {kitty.base}"


def cmd_balances(kitty, args):
    return as_json(money(kitty.balances()))


def cmd_settle(kitty, args):
    return as_json([{"from": sender, "to": receiver, "amount": core.format_cents(amount)}
                    for sender, receiver, amount in kitty.settle()])


def cmd_history(kitty, args):
    return as_json([{"date": date, "description": description,
                     "change": core.format_cents(change), "balance": core.format_cents(balance)}
                    for date, description, change, balance in kitty.history(args.name)])


def cmd_report(kitty, args):
    return as_json({category: money(totals) for category, totals in kitty.report().items()})


def cmd_export(kitty, args):
    count = kitty.export(args.file)
    return f"Exported {count} expense{'' if count == 1 else 's'} to {args.file}."


# --- Argument parsing -------------------------------------------------------

def build_parser():
    parser = Parser(prog="python3 -m kitty", description="Keep track of shared trip costs and who owes whom.")
    commands = parser.add_subparsers(dest="command", metavar="COMMAND", required=True)

    def command(subparsers, name, func, help, needs_kitty=True):
        sub = subparsers.add_parser(name, help=help, description=help)
        sub.set_defaults(func=func, needs_kitty=needs_kitty)
        return sub

    def group(name, help):
        sub = commands.add_parser(name, help=help, description=help)
        return sub.add_subparsers(dest="action", metavar="ACTION", required=True)

    command(commands, "init", cmd_init, "start a new kitty", needs_kitty=False).add_argument(
        "currency", help="main currency, e.g. EUR")

    members = group("member", "add, remove or list group members")
    command(members, "add", cmd_member_add, "add someone to the group").add_argument("name")
    command(members, "remove", cmd_member_remove, "remove someone from the group").add_argument("name")
    command(members, "list", cmd_member_list, "list the group")

    expenses = group("expense", "add, list or remove expenses")
    add = command(expenses, "add", cmd_expense_add, "record that someone paid for something")
    add.add_argument("payer", help="who paid")
    add.add_argument("amount", help="how much, e.g. 45.00")
    add.add_argument("description", nargs="+", help="what it was for")
    split = add.add_mutually_exclusive_group()
    split.add_argument("--among", metavar="A,B", help="split equally between only these people")
    split.add_argument("--exact", metavar="A=30,B=20", help="split by exact amounts (must add up to the total)")
    split.add_argument("--shares", metavar="A=2,B=1", help="split by shares")
    split.add_argument("--percent", metavar="A=60,B=40", help="split by percentages (must add up to 100)")
    add.add_argument("--currency", help="currency it was paid in (default: the main currency)")
    add.add_argument("--date", help="YYYY-MM-DD (default: today)")
    add.add_argument("--category", help=f"e.g. food (default: {core.DEFAULT_CATEGORY})")
    command(expenses, "list", cmd_expense_list, "list all expenses")
    command(expenses, "remove", cmd_expense_remove, "remove an expense by its ID").add_argument("id")

    payments = group("payment", "add, list or remove paybacks between people")
    pay = command(payments, "add", cmd_payment_add, "record that FROM paid TO back")
    pay.add_argument("sender", metavar="FROM")
    pay.add_argument("receiver", metavar="TO")
    pay.add_argument("amount")
    pay.add_argument("--currency", help="currency it was paid in (default: the main currency)")
    pay.add_argument("--date", help="YYYY-MM-DD (default: today)")
    command(payments, "list", cmd_payment_list, "list all payments")
    command(payments, "remove", cmd_payment_remove, "remove a payment by its ID").add_argument("id")

    rates = group("rate", "set exchange rates")
    rate = command(rates, "set", cmd_rate_set, "set how much one unit of CURRENCY is worth in the main currency")
    rate.add_argument("currency")
    rate.add_argument("rate")

    command(commands, "balances", cmd_balances, "show who is up (+) or down (-)")
    command(commands, "settle", cmd_settle, "suggest payments that even everything out")
    command(commands, "history", cmd_history, "show everything that affected one person").add_argument("name")
    command(commands, "report", cmd_report, "show each person's share of spending per category")
    command(commands, "export", cmd_export, "save expenses to a CSV file").add_argument("file")
    return parser


def main(argv=None):
    args = build_parser().parse_args(argv)
    try:
        if args.needs_kitty:
            output = args.func(core.Kitty.load(core.DATA_FILE), args)
        else:
            output = args.func(args)
    except core.KittyError as e:
        print(f"Error: {e}", file=sys.stderr)
        return 1
    print(output)
    return 0
import sys

from .cli import main

